def transformArray(nums):
    # Count the number of even (0s) and odd (1s) elements
    count_even = 0
    count_odd = 0

    for num in nums:
        if num % 2 == 0:
            count_even += 1
        else:
            count_odd += 1

    # Build array: all 0s (even), then all 1s (odd)
    return [0] * count_even + [1] * count_odd
